body.script:
const questions = [
  {
    question: "भारत की राजधानी क्या है?",
    options: ["मुंबई", "नई दिल्ली", "कोलकाता", "चेन्नई"],
    answer: 1
  },
  {
    question: "भारत का राष्ट्रीय पशु कौन है?",
    options: ["शेर", "हाथी", "बाघ", "घोड़ा"],
    answer: 2
  },
  {
    question: "ओडिशा की राजधानी क्या है?",
    options: ["कटक", "पुरी", "भुवनेश्वर", "संबलपुर"],
    answer: 2
  },
  {
    question: "भारत का संविधान कब लागू हुआ?",
    options: [
      "15 अगस्त 1947",
      "26 जनवरी 1950",
      "2 अक्टूबर 1950",
      "26 नवंबर 1949"
    ],
    answer: 1
  },
  {
    question: "भारत का राष्ट्रीय पक्षी कौन है?",
    options: ["तोता", "मोर", "कबूतर", "हंस"],
    answer: 1
  },
  {
    question: "सूर्य किस दिशा से निकलता है?",
    options: ["पश्चिम", "उत्तर", "दक्षिण", "पूर्व"],
    answer: 3
  },
  {
    question: "भारत में कुल कितने राज्य हैं?",
    options: ["27", "28", "29", "30"],
    answer: 1
  },
  {
    question: "भारत की मुद्रा क्या है?",
    options: ["डॉलर", "यूरो", "रुपया", "येन"],
    answer: 2
  },
  {
    question: "ओडिशा का प्रसिद्ध शास्त्रीय नृत्य कौन-सा है?",
    options: ["कथक", "भरतनाट्यम", "ओडिसी", "कुचिपुड़ी"],
    answer: 2
  },
  {
    question: "भारत का स्वतंत्रता दिवस कब मनाया जाता है?",
    options: [
      "26 जनवरी",
      "15 अगस्त",
      "2 अक्टूबर",
      "14 नवंबर"
    ],
    answer: 1
  }
];

let currentQuestion = 0;
let score = 0;
let answered = false;

const questionElement = document.getElementById("question");
const optionsElement = document.getElementById("options");
const feedbackElement = document.getElementById("feedback");
const progressElement = document.getElementById("progress");
const scoreElement = document.getElementById("score");
const nextButton = document.getElementById("nextButton");

function loadQuestion() {
  answered = false;

  const q = questions[currentQuestion];

  progressElement.textContent =
    `सवाल ${currentQuestion + 1}/${questions.length}`;

  scoreElement.textContent = `स्कोर: ${score}`;
  questionElement.textContent = q.question;
  feedbackElement.textContent = "";
  optionsElement.replaceChildren();

  q.options.forEach((option, index) => {
    const button = document.createElement("button");

    button.className = "option";
    button.textContent =
      `${String.fromCharCode(65 + index)}. ${option}`;

    button.onclick = () => checkAnswer(index, button);

    optionsElement.appendChild(button);
  });

  nextButton.disabled = true;

  nextButton.textContent =
    currentQuestion === questions.length - 1
      ? "रिज़ल्ट देखें"
      : "अगला सवाल →";
}

function checkAnswer(selectedIndex, selectedButton) {
  if (answered) return;

  answered = true;

  const q = questions[currentQuestion];
  const buttons = optionsElement.querySelectorAll("button");

  buttons.forEach(button => {
    button.disabled = true;
  });

  if (selectedIndex === q.answer) {
    score++;
    selectedButton.classList.add("correct");
    feedbackElement.textContent = "✅ सही जवाब!";
  } else {
    selectedButton.classList.add("wrong");
    buttons[q.answer].classList.add("correct");

    feedbackElement.textContent =
      `❌ गलत जवाब। सही उत्तर: ${q.options[q.answer]}`;
  }

  scoreElement.textContent = `स्कोर: ${score}`;
  nextButton.disabled = false;
}

function nextQuestion() {
  if (!answered) return;

  currentQuestion++;

  if (currentQuestion < questions.length) {
    loadQuestion();
  } else {
    showResult();
  }
}

function showResult() {
  document.getElementById("quiz").classList.add("hidden");
  document.getElementById("result").classList.remove("hidden");

  document.getElementById("finalScore").textContent =
    `आपका स्कोर: ${score}/${questions.length}`;

  const percentage = (score / questions.length) * 100;

  let message;

  if (percentage >= 80) {
    message = "बहुत बढ़िया! आपकी तैयारी अच्छी है।";
  } else if (percentage >= 50) {
    message = "अच्छा प्रयास! अभ्यास जारी रखें।";
  } else {
    message = "अभी और अभ्यास करें। आप बेहतर कर सकते हैं!";
  }

  document.getElementById("message").textContent = message;
}

function restartQuiz() {
  currentQuestion = 0;
  score = 0;

  document.getElementById("result").classList.add("hidden");
  document.getElementById("quiz").classList.remove("hidden");

  loadQuestion();
}

loadQuestion();
